import numpy as np
K=128
def oh(v,K=K):
    E=np.zeros((len(v),K)); E[np.arange(len(v)),v]=1; return E
col={3:X[:,0],5:X[:,1],7:X[:,2],9:X[:,3]}
fit=np.arange(300); ho=np.arange(300,400)
def cuttest(L, positions, extra=None):
    sites=[f"resid{L}@{p}" for p in positions]
    Afit=acts(X[fit],sites); Aho=acts(X[ho],sites)
    hook={}
    r2s=[]
    for p in positions:
        s=f"resid{L}@{p}"
        coef,_,_,_=np.linalg.lstsq(oh(col[p][fit]),Afit[s],rcond=None)
        pr=oh(col[p][ho])@coef
        hook[s]=pr
        r2s.append(round(float(1-((Aho[s]-pr)**2).sum()/((Aho[s]-Aho[s].mean(0))**2).sum()),3))
    others=[q for q in range(11) if q not in positions]
    Mo=acts(X[fit],[f"resid{L}@{q}" for q in others])
    for q in others: hook[f"resid{L}@{q}"]=Mo[f"resid{L}@{q}"].mean(0)
    lg=run(X[ho],hook=hook); base=run(X[ho]).argmax(1)
    return (lg.argmax(1)==base).mean(), r2s
for L in [1,3,5,7]:
    for pos in [[9],[7,9],[5,7,9],[3,5,7,9]]:
        acc,r2=cuttest(L,pos)
        print(L,pos,round(float(acc),3),r2)

